from flask import Flask, request, session, jsonify, abort, render_template_string
import hashlib
import hmac
import os
import time
import subprocess
import tempfile
import shlex

app = Flask(__name__)
app.secret_key = os.urandom(32)

CSRF_TOKEN_LIFETIME = 3600
ROLES = {'admin': 3, 'editor': 2, 'viewer': 1}

def generate_csrf_token(session_id, timestamp):
    """Generate HMAC-based CSRF token tied to session and time."""
    msg = f"{session_id}:{timestamp}".encode()
    return hmac.new(app.secret_key, msg, hashlib.sha256).hexdigest()

def validate_csrf_token(token, session_id):
    """Validate CSRF token within acceptable time window."""
    current_time = int(time.time())
    for offset in range(0, CSRF_TOKEN_LIFETIME, 1):
        candidate_time = current_time - offset
        expected = generate_csrf_token(session_id, candidate_time)
        if hmac.compare_digest(token, expected):
            return True
    return False

def require_role(minimum_role):
    """Decorator to enforce minimum role level."""
    def decorator(f):
        def wrapper(*args, **kwargs):
            user_role = session.get('role', 'viewer')
            if ROLES.get(user_role, 0) < ROLES.get(minimum_role, 999):
                abort(403)
            return f(*args, **kwargs)
        wrapper.__name__ = f.__name__
        return wrapper
    return decorator

def validate_c_filename(filename):
    """Ensure filename is safe and ends with .c extension."""
    if not filename:
        return False
    basename = os.path.basename(filename)
    if basename != filename:
        return False
    if not basename.endswith('.c'):
        return False
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.')
    if not all(c in allowed_chars for c in basename):
        return False
    return True

def compile_c_file(filepath, output_path):
    """Compile a C file with restricted flags."""
    cmd = ['gcc', '-Wall', '-Werror', '-O2', '-o', output_path, filepath]
    result = subprocess.run(cmd, capture_output=True, timeout=30, text=True)
    return result.returncode, result.stdout, result.stderr

class CSRFProtection:
    """Middleware-style CSRF protection for state-changing requests."""

    SAFE_METHODS = frozenset(['GET', 'HEAD', 'OPTIONS'])
    PROTECTED_ENDPOINTS = frozenset(['upload_file', 'delete_file', 'compile_file'])

    @staticmethod
    def is_request_protected(endpoint, method):
        """Determine if request needs CSRF validation."""
        if method in CSRFProtection.SAFE_METHODS:
            return False
        if endpoint in CSRFProtection.PROTECTED_ENDPOINTS:
            return True
        return False

    @staticmethod
    def check_origin(request_obj):
        """Validate Origin/Referer header as defense-in-depth."""
        origin = request_obj.headers.get('Origin', '')
        referer = request_obj.headers.get('Referer', '')
        host = request_obj.host_url.rstrip('/')

        if origin:
            return origin.rstrip('/') == host
        if referer:
            from urllib.parse import urlparse
            parsed = urlparse(referer)
            return f"{parsed.scheme}://{parsed.netloc}".rstrip('/') == host
        # If neither header present, allow request (for API clients)
        return True

@app.before_request
def csrf_protect():
    """Apply CSRF protection before each request."""
    if not CSRFProtection.is_request_protected(request.endpoint, request.method):
        return None

    # Check origin header first
    if not CSRFProtection.check_origin(request):
        abort(403, description="Origin validation failed")

    # For multipart form uploads, check token in form data
    token = request.headers.get('X-CSRF-Token') or request.form.get('csrf_token')
    session_id = session.get('session_id', '')

    if not token or not session_id:
        abort(403, description="Missing CSRF token")

    if not validate_csrf_token(token, session_id):
        abort(403, description="Invalid CSRF token")

@app.route('/api/token', methods=['GET'])
def get_csrf_token():
    """Issue a new CSRF token for the current session."""
    if 'session_id' not in session:
        session['session_id'] = os.urandom(16).hex()
    timestamp = int(time.time())
    token = generate_csrf_token(session['session_id'], timestamp)
    return jsonify({'csrf_token': token, 'expires_in': CSRF_TOKEN_LIFETIME})

@app.route('/api/upload', methods=['POST'], endpoint='upload_file')
@require_role('editor')
def upload_file():
    """Upload a C source file for processing."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if not validate_c_filename(file.filename):
        return jsonify({'error': 'Invalid filename'}), 400

    upload_dir = os.path.join(tempfile.gettempdir(), 'c_uploads', session['session_id'])
    os.makedirs(upload_dir, exist_ok=True)

    filepath = os.path.join(upload_dir, file.filename)
    file.save(filepath)

    return jsonify({'message': 'File uploaded', 'filename': file.filename}), 201

@app.route('/api/compile', methods=['POST'], endpoint='compile_file')
@require_role('editor')
def compile_endpoint():
    """Compile an uploaded C file."""
    data = request.get_json()
    if not data or 'filename' not in data:
        return jsonify({'error': 'Filename required'}), 400

    filename = data['filename']
    if not validate_c_filename(filename):
        return jsonify({'error': 'Invalid filename'}), 400

    upload_dir = os.path.join(tempfile.gettempdir(), 'c_uploads', session['session_id'])
    filepath = os.path.join(upload_dir, filename)

    if not os.path.isfile(filepath):
        return jsonify({'error': 'File not found'}), 404

    output_path = filepath.replace('.c', '.out')
    retcode, stdout, stderr = compile_c_file(filepath, output_path)

    return jsonify({
        'success': retcode == 0,
        'stdout': stdout,
        'stderr': stderr
    })

@app.route('/api/delete', methods=['POST'], endpoint='delete_file')
@require_role('admin')
def delete_file():
    """Delete an uploaded file."""
    data = request.get_json()
    if not data or 'filename' not in data:
        return jsonify({'error': 'Filename required'}), 400

    filename = data['filename']
    if not validate_c_filename(filename):
        return jsonify({'error': 'Invalid filename'}), 400

    upload_dir = os.path.join(tempfile.gettempdir(), 'c_uploads', session['session_id'])
    filepath = os.path.join(upload_dir, filename)

    if os.path.isfile(filepath):
        os.remove(filepath)
        return jsonify({'message': 'File deleted'})
    return jsonify({'error': 'File not found'}), 404

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
